    function createCopyField(label, value, icon = '📌') {
        const container = document.createElement('div');
        Object.assign(container.style, {
            background: '#ffffff',
            border: '1px solid #ddd',
            borderRadius: '6px',
            padding: '12px',
            display: 'flex',
            flexDirection: 'column',
            gap: '8px'
        });

        // Label
        const labelEl = document.createElement('div');
        labelEl.textContent = `${icon} ${label}`;
        Object.assign(labelEl.style, {
            fontWeight: 'bold',
            color: '#555',
            fontSize: '12px'
        });
        container.appendChild(labelEl);

        // Value container
        const valueContainer = document.createElement('div');
        Object.assign(valueContainer.style, {
            display: 'flex',
            gap: '8px',
            alignItems: 'flex-start'
        });

        // Value display
        const valueEl = document.createElement('div');
        valueEl.textContent = value;
        Object.assign(valueEl.style, {
            flex: '1',
            color: '#333',
            fontSize: '12px',
            fontFamily: 'Courier New, monospace',
            background: '#f5f5f5',
            padding: '8px',
            borderRadius: '4px',
            wordWrap: 'break-word',
            lineHeight: '1.4',
            maxHeight: '150px',
            overflowY: 'auto'
        });

        // Copy button
        const copyBtn = document.createElement('button');
        copyBtn.textContent = 'Copy';
        Object.assign(copyBtn.style, {
            padding: '6px 16px',
            background: '#28a745',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '12px',
            fontWeight: 'bold',
            whiteSpace: 'nowrap'
        });
        copyBtn.onclick = async () => {
            try {
                await navigator.clipboard.writeText(value);
                const originalText = copyBtn.textContent;
                const originalBg = copyBtn.style.background;
                copyBtn.textContent = '✓ Copied!';
                copyBtn.style.background = '#0066cc';
                setTimeout(() => {
                    copyBtn.textContent = originalText;
                    copyBtn.style.background = originalBg;
                }, 1500);
            } catch (err) {
                console.error('Copy failed:', err);
                alert('❌ Failed to copy');
            }
        };

        valueContainer.appendChild(valueEl);
        valueContainer.appendChild(copyBtn);
        container.appendChild(valueContainer);

        return container;
    }

    function showSPMModal() {
        const modal = document.getElementById('spm-copy-modal');
        const content = document.getElementById('spm-modal-content');

        if (!modal || !content) {
            initializeSPMModal();
            return showSPMModal();
        }

        // Clear existing content
        content.innerHTML = '';

        // Extract data
        const data = extractSummaryData();

        // Add fields in order
        const fields = [
            { label: 'Opened By', value: data.openedBy, icon: '🔓' },
            { label: 'Requesting Member Firm', value: data.memberFirm, icon: '🏢' },
            { label: 'Business Justification', value: data.businessJustification, icon: '📝' },
            { label: 'Number', value: data.number, icon: '🎫' }
        ];

        let hasData = false;
        fields.forEach(field => {
            if (field.value && field.value !== 'N/A') {
                content.appendChild(createCopyField(field.label, field.value, field.icon));
                hasData = true;
            }
        });

        if (!hasData) {
            const noData = document.createElement('p');
            noData.textContent = '⚠️ No data available to copy';
            Object.assign(noData.style, {
                color: '#999',
                fontSize: '13px',
                textAlign: 'center',
                padding: '20px'
            });
            content.appendChild(noData);
        }

        modal.style.display = 'flex';
    }

    function copySPMData() {
        showSPMModal();
    }

